<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserPersonalApiKey\Application\Usecase\Revoke;

use RuntimeException;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Domain\UserPersonalApiKey;
use Civi\Lughauth\Shared\Exception\ConstraintException;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFail;

class UserPersonalApiKeyRevokeCheck
{
    public function __construct(public readonly UserPersonalApiKey $current)
    {
    }
    public function reject(RuntimeException|ConstraintFail $fail): void
    {
        if ($fail instanceof ConstraintFail) {
            throw ConstraintException::ofFail($fail);
        } else {
            throw $fail;
        }
    }
}
